function renderKpis() {
  const k = DATA.kpis;
  const items = [
    ['遊戲數', fmt.format(k.games), '三個月資料集內遊戲總量'],
    ['供應商數', fmt.format(k.providers), '內容供給廣度'],
    ['總投注（萬）', wan(k.totalBetWan), '三個月消費規模'],
    ['GGR（萬）', wan(k.ggrWan), '商業價值'],
    ['加權 RTP', pct2(k.weightedRtp), '按投注加權後的派彩比例'],
    ['前三大供應商占比', pct(k.top3ProviderShare), '供應商集中度'],
    ['前五大遊戲占比', pct(k.top5GameShare), '遊戲集中度'],
    ['總 Spin 數', fmt.format(k.totalSpins), '遊玩互動量'],
  ];
  document.querySelector('#kpiGrid').innerHTML = items.map(([label, value, note]) => `
    <article class="kpi"><label>${label}</label><strong>${value}</strong><span>${note}</span></article>
  `).join('');
}

function renderBars(el, rows, nameKey, valueKey, options = {}) {
  const max = Math.max(...rows.map(r => Number(r[valueKey]) || 0), 1);
  el.innerHTML = rows.map((r, i) => {
    const value = Number(r[valueKey]) || 0;
    const width = Math.max(1, value / max * 100);
    const color = options.color || (i % 4 === 0 ? '#f59e0b' : i % 4 === 1 ? '#3b82f6' : i % 4 === 2 ? '#10b981' : '#8b5cf6');
    const display = options.percent ? pct(value) : (options.decimal ? fmt1.format(value) : wan(value));
    return `<div class="bar-row">
      <div class="bar-name" title="${safe(r[nameKey])}">${safe(r[nameKey])}</div>
      <div class="bar-track"><div class="bar-fill" style="width:${width}%;background:${color}"></div></div>
      <div class="bar-value">${display}</div>
    </div>`;
  }).join('');
}

function renderLineChart() {
  const el = document.querySelector('#monthlyLine');
  const rows = DATA.monthly;
  const width = 640, height = 260, pad = 42;
  const max = Math.max(...rows.flatMap(r => [r.bet, r.ggr]));
  const x = i => pad + i * ((width - pad * 2) / (rows.length - 1));
  const y = v => height - pad - (v / max) * (height - pad * 2);
  const line = key => rows.map((r, i) => `${x(i)},${y(r[key])}`).join(' ');
  el.innerHTML = `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Monthly bet and GGR trend">
    <line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}" stroke="#334155"/>
    <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${height-pad}" stroke="#334155"/>
    <polyline points="${line('bet')}" fill="none" stroke="#3b82f6" stroke-width="4"/>
    <polyline points="${line('ggr')}" fill="none" stroke="#f59e0b" stroke-width="4"/>
    ${rows.map((r,i) => `<text x="${x(i)}" y="${height-13}" text-anchor="middle" font-size="13" fill="#9fb0c1">${r.month.slice(5)}</text>`).join('')}
    ${rows.map((r,i) => `<circle cx="${x(i)}" cy="${y(r.bet)}" r="5" fill="#3b82f6"><title>${r.month} Bet: ${wan(r.bet)}</title></circle>`).join('')}
    ${rows.map((r,i) => `<circle cx="${x(i)}" cy="${y(r.ggr)}" r="5" fill="#f59e0b"><title>${r.month} GGR: ${wan(r.ggr)}</title></circle>`).join('')}
    <text x="${width-160}" y="24" fill="#3b82f6" font-size="13">總投注</text>
    <text x="${width-82}" y="24" fill="#f59e0b" font-size="13">GGR</text>
  </svg>`;
}

function table(el, headers, rows) {
  el.innerHTML = `<thead><tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody>`;
}

function deltaClass(v) { return v == null ? '' : v >= 0 ? 'delta-up' : 'delta-down'; }

function renderProviderTable() {
  const rows = DATA.providers.map(r => `<tr>
    <td>${r.provider}</td><td>${fmt.format(r.game_count)}</td><td>${wan(r.total_bet_wan)}</td>
    <td>${pct(r.bet_share)}</td><td>${wan(r.total_ggr_wan)}</td><td>${pct(r.ggr_share)}</td>
    <td>${(r.total_rtp || 0).toFixed(2)}%</td><td>${wan(r.mar_bet_wan)}</td><td>${wan(r.apr_bet_wan)}</td><td>${wan(r.may_bet_wan)}</td>
    <td class="${deltaClass(r.apr_to_may_bet_growth)}">${pct(r.apr_to_may_bet_growth)}</td>
  </tr>`);
  table(document.querySelector('#providerTable'), ['供應商','遊戲數','總投注','投注占比','GGR','GGR占比','RTP','3月','4月','5月','4→5月'], rows);
}

function initGameControls() {
  const providers = ['全部', ...new Set(DATA.games.map(g => g.provider))];
  document.querySelector('#providerFilter').innerHTML = providers.map(p => `<option value="${p}">${p}</option>`).join('');
  document.querySelector('#providerFilter').addEventListener('change', renderGames);
  document.querySelector('#gameMetric').addEventListener('change', renderGames);
}

function renderGames() {
  const provider = document.querySelector('#providerFilter').value;
  const metric = document.querySelector('#gameMetric').value;
  let rows = DATA.games.filter(g => provider === '全部' || g.provider === provider);
  rows = rows.sort((a,b) => (b[metric] || 0) - (a[metric] || 0));
  document.querySelector('#gameCount').textContent = `${rows.length} 款遊戲`;
  renderBars(document.querySelector('#gameBars'), rows.slice(0, 18).map(r => ({ ...r, display_name: gameName(r) })), 'display_name', metric, { decimal: metric !== 'total_bet_wan' && metric !== 'ggr_wan' });
  const body = rows.slice(0, 20).map(r => `<tr>
    <td>${r.provider}</td><td>${gameName(r)}</td><td>${fmt.format(r.players || 0)}</td>
    <td>${fmt1.format(r.spins_per_player || 0)}</td><td>${wan(r.total_bet_wan)}</td><td>${wan(r.ggr_wan)}</td>
    <td>${(r.rtp || 0).toFixed(2)}%</td><td>${fmt1.format(r.max_multiplier || 0)}</td><td>${fmt1.format(r.hits_100x_per_m_spins || 0)}</td>
  </tr>`);
  table(document.querySelector('#gameTable'), ['供應商','遊戲','玩家數','每人Spin','投注','GGR','RTP','最大倍率','100x/M'], body);
}

let currentSignal = 'growth';
function renderSignal() {
  const rows = DATA.signals[currentSignal];
  const el = document.querySelector('#signalTable');
  if (currentSignal === 'growth') {
    table(el, ['供應商','遊戲','3月','4月','5月','3→5月','RTP','RTP區間'], rows.map(r => `<tr><td>${r.provider}</td><td>${gameName(r)}</td><td>${wan(r.mar_bet_wan)}</td><td>${wan(r.apr_bet_wan)}</td><td>${wan(r.may_bet_wan)}</td><td class="${deltaClass(r.mar_to_may_bet_growth)}">${pct(r.mar_to_may_bet_growth)}</td><td>${(r.total_rtp||0).toFixed(2)}%</td><td>${fmt1.format(r.rtp_range || 0)}</td></tr>`));
  } else if (currentSignal === 'decline') {
    table(el, ['供應商','遊戲','3月','4月','5月','4→5月','RTP','RTP區間'], rows.map(r => `<tr><td>${r.provider}</td><td>${gameName(r)}</td><td>${wan(r.mar_bet_wan)}</td><td>${wan(r.apr_bet_wan)}</td><td>${wan(r.may_bet_wan)}</td><td class="${deltaClass(r.apr_to_may_bet_growth)}">${pct(r.apr_to_may_bet_growth)}</td><td>${(r.total_rtp||0).toFixed(2)}%</td><td>${fmt1.format(r.rtp_range || 0)}</td></tr>`));
  } else if (currentSignal === 'volatility') {
    table(el, ['供應商','遊戲','投注','Spin數','最大倍率','100x/M','50x/M','RTP'], rows.map(r => `<tr><td>${r.provider}</td><td>${gameName(r)}</td><td>${wan(r.total_bet_wan)}</td><td>${fmt.format(r.spins||0)}</td><td>${fmt1.format(r.max_multiplier||0)}</td><td>${fmt1.format(r.hits_100x_per_m_spins||0)}</td><td>${fmt1.format(r.hits_50x_per_m_spins||0)}</td><td>${(r.rtp||0).toFixed(2)}%</td></tr>`));
  } else {
    table(el, ['供應商','遊戲','玩家數','每人Spin','投注','平均下注','RTP'], rows.map(r => `<tr><td>${r.provider}</td><td>${gameName(r)}</td><td>${fmt.format(r.players||0)}</td><td>${fmt1.format(r.spins_per_player||0)}</td><td>${wan(r.total_bet_wan)}</td><td>${fmt1.format(r.avg_bet_per_spin||0)}</td><td>${(r.rtp||0).toFixed(2)}%</td></tr>`));
  }
}

function initSignals() {
  document.querySelectorAll('.signal-tabs button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.signal-tabs button').forEach(b => b.classList.remove('selected'));
      btn.classList.add('selected');
      currentSignal = btn.dataset.signal;
      renderSignal();
    });
  });
}

function renderDevPicks() {
  const linkSet = (game, provider) => {
    const slug = game
      .toLowerCase()
      .replace(/&/g, 'and')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    const slotCatalogUrl = `https://slotcatalog.com/en/slots/${slug}`;
    const casinoGuruUrl = `https://casino.guru/${slug}-slot-play-free`;
    const providerUrl = provider.includes('Pragmatic')
      ? 'https://www.pragmaticplay.com/en/games/'
      : provider.includes('PG Soft')
        ? 'https://www.pgsoft.com/en/games/'
        : provider.includes('AsiaGaming')
          ? 'https://www.m88.com/casino?categories=slot-games'
          : slotCatalogUrl;
    return `<div class="link-stack">
      <a href="${slotCatalogUrl}" target="_blank" rel="noopener">SlotCatalog Demo</a>
      <a href="${casinoGuruUrl}" target="_blank" rel="noopener">Casino Guru</a>
      <a href="${providerUrl}" target="_blank" rel="noopener">Provider</a>
    </div>`;
  };
  const rows = DEV_CANDIDATES.map((r, i) => `<tr>
    <td>${i + 1}</td>
    <td><strong>${r[0]}</strong><span>${r[1]}</span></td>
    <td>${r[2]}</td>
    <td>${r[3]}</td>
    <td>${r[4]}</td>
    <td>${linkSet(r[0], r[1])}</td>
    <td>${r[5]}</td>
  </tr>`);
  table(document.querySelector('#devPicksTable'), ['#', '遊戲 / 供應商', '建議開發方向', 'IVI 內部證據', '線上參考對照', 'Demo / 資訊', '推薦理由'], rows);
}

function renderBenchmark() {
  document.querySelector('#benchmarkCards').innerHTML = DATA.benchmark.map(x => {
    const detail = BENCHMARK_DETAILS[x.source] || {};
    return `<article class="matrix-card benchmark-card">
    <h3>${x.source}</h3>
    <p><b>外部訊號</b><br>${x.signal}</p>
    <p><b>交叉使用</b><br>${x.crossUse}</p>
    <p><b>決策用途</b><br>${x.decision}</p>
    <div class="benchmark-extra">
      <p><b>排行 / 趨勢</b><br>${detail.ranking || '-'}</p>
      <div class="trend-list">
        <div class="trend-list-title">目前排行 / 趨勢項目</div>
        ${(detail.trends || []).map(([group, game, provider, url]) => `<div class="trend-row">
          <span>${group}</span>
          <strong>${url ? `<a href="${url}" target="_blank" rel="noopener">${game}</a>` : game}</strong>
          <em>${provider}</em>
        </div>`).join('')}
      </div>
      <p><b>遊戲資訊</b><br>${detail.gameInfo || '-'}</p>
      <p><b>範例 / 可追蹤遊戲</b><br>${(detail.examples || []).map(item => `<span class="pill">${item}</span>`).join('')}</p>
      <div class="benchmark-links">${(detail.links || []).map(([label, url]) => `<a href="${url}" target="_blank" rel="noopener">${label}</a>`).join('')}</div>
    </div>
  </article>`;
  }).join('');
}

function renderDiscussion() {
  document.querySelector('#discussionCards').innerHTML = DISCUSSION.map(card => `<article class="discussion-card">
    <div class="discussion-card-head">
      <h3>${card.title}</h3>
      <span>${card.tag}</span>
    </div>
    <ul>${card.points.map(point => `<li>${point}</li>`).join('')}</ul>
  </article>`).join('');
}

function initNav() {
  const links = [...document.querySelectorAll('nav a')];
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      links.forEach(a => a.classList.toggle('active', a.getAttribute('href') === `#${entry.target.id}`));
    });
  }, { rootMargin: '-35% 0px -55% 0px' });
  document.querySelectorAll('.section').forEach(section => observer.observe(section));
}

